import axios from "axios";

// Fetch basic GitHub Discussions metrics for a repo (owner/repo)
export async function fetchDiscussions(repo) {
  if (!repo) return { discussions_count: 0, recent_activity_last_6mo: 0 };
  const url = `https://api.github.com/repos/${repo}/discussions`;
  const headers = {};
  if (process.env.GH_TOKEN) headers.Authorization = `Bearer ${process.env.GH_TOKEN}`;
  try {
    const resp = await axios.get(url, { headers, timeout: 15000 });
    const items = resp.data || [];
    // count recent activity: discussions updated in last 6 months
    const now = new Date();
    const sixMonthsAgo = new Date(now);
    sixMonthsAgo.setMonth(now.getMonth() - 6);
    let recent = 0;
    for (const d of items) {
      const updated = new Date(d.updated_at || d.created_at || 0);
      if (updated >= sixMonthsAgo) recent += 1;
    }
    return { discussions_count: items.length, recent_activity_last_6mo: recent };
  } catch (e) {
    return { discussions_count: 0, recent_activity_last_6mo: 0, _error: e?.message || String(e) };
  }
}

import axios from "axios";

const DEFAULT_TIMEOUT = 10000;

// Go modules don't have a public global download count API. We can fetch
// the list of versions from the Go proxy and return a diagnostic (versions_count)
// while returning weekly_downloads: 0 and an explanatory _error so callers know
// why counts are missing.
export async function fetchGo(modulePath) {
  if (!modulePath) return { weekly_downloads: 0 };
  try {
    const safe = encodeURIComponent(modulePath);
    const listUrl = `https://proxy.golang.org/${safe}/@v/list`;
    const { data } = await axios.get(listUrl, { timeout: DEFAULT_TIMEOUT });
    // response is newline-separated versions
    const versions = (data || '').split(/\r?\n/).filter(Boolean);
    return { weekly_downloads: 0, versions_count: versions.length, latest_version: versions[versions.length-1] || null, _error: 'no-public-downloads-for-go' };
  } catch (err) {
    return { weekly_downloads: 0, _error: `go proxy failed: ${err?.response?.status || ''} ${err?.message || ''}`.trim() };
  }
}

import axios from "axios";

// Packagist provides package downloads (total); we'll proxy to a weekly approximation by dividing by 52
export async function fetchPackagist(pkg) {
  const safe = encodeURIComponent(pkg);
  const url = `https://repo.packagist.org/p2/${safe}.json`;
  try {
    const { data } = await axios.get(url, { timeout: 15000 });
    // The packagist p2 response includes packages -> {name: [versions...]}
    // Sum downloads across versions if present (some endpoints include downloads)
    let total = 0;
    const pkgData = data?.packages?.[pkg] || data?.packages?.[Object.keys(data?.packages || {})[0]];
    if (pkgData && Array.isArray(pkgData)) {
      for (const v of pkgData) {
        if (typeof v.downloads === 'number') total += v.downloads;
      }
    }
    // fallback: try metadata endpoint for total downloads
    if (total === 0) {
      try {
        const metaUrl = `https://packagist.org/packages/${safe}.json`;
        const { data: meta } = await axios.get(metaUrl, { timeout: 15000 });
        total = meta?.package?.downloads?.total || 0;
      } catch (e) {
        // ignore
      }
    }
    return { weekly_downloads: Math.round(total / 52), total_downloads: total };
  } catch (e) {
    return { weekly_downloads: 0, _error: e?.message || String(e) };
  }
}

import axios from "axios";

const DEFAULT_TIMEOUT = 10000;

// Maven Central doesn't provide public per-artifact download counts. We'll
// query the search API for the artifact and return a diagnostic: 'found' and
// 'version_count', and return weekly_downloads: 0 with an _error explaining why.
export async function fetchMaven(coords) {
  try {
    if (!coords || !coords.group || !coords.artifact) return { weekly_downloads: 0 };
    const q = `g:${coords.group} AND a:${coords.artifact}`;
    const url = `https://search.maven.org/solrsearch/select?q=${encodeURIComponent(q)}&rows=20&wt=json`;
    const { data } = await axios.get(url, { timeout: DEFAULT_TIMEOUT });
    const docs = data?.response?.docs || [];
    const found = docs.length > 0;
    const versions = found ? (docs[0].v ? 1 : 0) : 0; // solr returns 'v' latest version, but not a full version list here
    return { weekly_downloads: 0, found, version_count: versions, latest_version: docs[0]?.v || null, _error: 'maven: no-public-downloads' };
  } catch (err) {
    return { weekly_downloads: 0, _error: `maven query failed: ${err?.response?.status || ''} ${err?.message || ''}`.trim() };
  }
}

import axios from "axios";

const DEFAULT_TIMEOUT = 15000;
function wait(ms) { return new Promise((r) => setTimeout(r, ms)); }

// Fetch NuGet package download counts.
// Preferred: use search endpoint which includes totalDownloads.
// Fallback: parse registration index if needed.
export async function fetchNuGet(id) {
  const pkg = encodeURIComponent(id);
  let lastErr = null;

  // 1) Try search API which returns totalDownloads in a simple shape
  const searchUrl = `https://api-v2v3search-0.nuget.org/query?q=packageid:${pkg}&prerelease=false`;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const { data } = await axios.get(searchUrl, { timeout: DEFAULT_TIMEOUT });
      const first = data?.data?.[0] || null;
      if (first && typeof first.totalDownloads === 'number') {
        const total = first.totalDownloads;
        return { weekly_downloads: Math.round(total / 52), total_downloads: total };
      }
      break;
    } catch (err) {
      lastErr = err;
      const backoff = attempt * 300;
      await wait(backoff);
      continue;
    }
  }

  // 2) Fallback: parse registration index pages
  try {
    const indexUrl = "https://api.nuget.org/v3/index.json";
    const { data: idx } = await axios.get(indexUrl, { timeout: DEFAULT_TIMEOUT });
    const regResource = (idx.resources || []).find(r => String(r["@type"] || "").toLowerCase().includes("registrationsbaseurl"));
    const regBase = regResource && regResource["@id"] ? regResource["@id"] : null;
    if (!regBase) throw new Error('no-registrations-base');

    const regUrl = `${regBase}${id.toLowerCase()}/index.json`;
    const { data: reg } = await axios.get(regUrl, { timeout: DEFAULT_TIMEOUT });

    let total = 0;
    for (const page of reg.items || []) {
      // page may contain items or a subpage with items
      const items = page.items || page; // defensive
      for (const item of (page.items || [])) {
        const entry = item.catalogEntry || item;
        // check multiple common property names
        const d = entry?.downloads ?? entry?.totalDownloads ?? entry?.downloadCount ?? 0;
        total += d || 0;
      }
    }

    return { weekly_downloads: Math.round(total / 52), total_downloads: total };
  } catch (err) {
    lastErr = lastErr || err;
  }

  return { weekly_downloads: 0, _error: lastErr ? `${lastErr?.response?.status || ''} ${lastErr?.message || ''}`.trim() : 'nuget: no-data' };
}

